class Solution {
    public double averageWaitingTime(int[][] customers){
        long finish=0,totalWait=0;
        for(int[] customer:customers){
            finish=Math.max(finish,customer[0])+customer[1];
            totalWait+=finish-customer[0];
        }
        return (double)totalWait/customers.length;
    }
}

code.kotlin:
class Solution {
    fun averageWaitingTime(customers:Array<IntArray>):Double{
        var finish=0L;
        var totalWait=0L;
        for(customer in customers){
            finish=maxOf(finish,customer[0].toLong())+customer[1];
            totalWait+=finish-customer[0]
        };
        return totalWait.toDouble()/customers.size
    }
}

code.cpp:
class Solution {
    public: double averageWaitingTime(vector<vector<int>>& customers){
        long long finish=0,totalWait=0;
        for(auto& customer:customers){
            finish=max(finish,1LL*customer[0])+customer[1];
            totalWait+=finish-customer[0];
        }
        return (double)totalWait/customers.size();
    }
};
